    const live=ss.filter(s=>s.status!=="completed").slice(0,10);
    $("sessions").innerHTML=live.length?live.map(s=>'<div class="s"><span class="dot '+esc(s.status)+'"></span><div><b>'+esc(LBL[s.status]||s.status)+'</b> <span class="mut">'+esc(s.folder||s.id.slice(0,8))+(s.contextPct!=null?' \xB7 '+Math.round(s.contextPct)+'% context':'')+'</span><div>'+esc(s.task||"")+'</div>'+(s.needsYou?'<div class="mut">'+esc(s.needsYou)+'</div>':"")+'</div></div>').join(""):'<div class="mut">No active sessions.</div>';
    const need=ss.filter(s=>s.status==="awaiting_approval"||s.status==="blocked"||s.status==="failed").map(s=>s.id+s.status+s.lastEventAt).join("|");
